// IsSolid is BlockStateBase.isSolid.
func IsSolid(state uint32) bool {
	lo, hi := 0, len(solidRanges)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		r := solidRanges[mid]
		switch {
		case state < r.Min:
			hi = mid - 1
		case state > r.Max:
			lo = mid + 1
		default:
			return true
		}
	}
	return false
}
